import type { shiftInfo } from '../../types/shift.types';

export type DelayRuleFormRow = {
    delay_minutes: string;
    delay_calculation_method: string;
};

/** Build default rows for delay minutes + amount; supports legacy single values or paired JSON arrays from API. */
export function parseDelayRulesFromShift(shift: shiftInfo | null | undefined): DelayRuleFormRow[] {
    if (!shift) {
        return [{ delay_minutes: '', delay_calculation_method: '' }];
    }

    const rawMinutes = shift.delay_minutes;
    const rawAmount = shift.delay_calculation_method ?? '';

    const minutesStr = rawMinutes != null && rawMinutes !== '' ? String(rawMinutes).trim() : '';
    const amountStr = String(rawAmount).trim();

    if (minutesStr.startsWith('[') && amountStr.startsWith('[')) {
        try {
            const minutesArr = JSON.parse(minutesStr) as unknown;
            const amountsArr = JSON.parse(amountStr) as unknown;
            if (
                Array.isArray(minutesArr) &&
                Array.isArray(amountsArr) &&
                minutesArr.length > 0 &&
                minutesArr.length === amountsArr.length
            ) {
                return minutesArr.map((m, i) => ({
                    delay_minutes: String(m ?? ''),
                    delay_calculation_method: String((amountsArr as unknown[])[i] ?? ''),
                }));
            }
        } catch {
            // fall through to single-row legacy
        }
    }

    return [
        {
            delay_minutes: minutesStr,
            delay_calculation_method: amountStr,
        },
    ];
}

/** Normalize API time values for HTML `type="time"` (expects `HH:mm`). */
export function normalizeTimeForInput(v: string | null | undefined): string {
    if (v == null || v === '') return '';
    const s = String(v).trim();
    const hm = s.match(/^(\d{2}):(\d{2})(?::\d{2})?$/);
    if (hm) return `${hm[1]}:${hm[2]}`;
    const iso = s.match(/T(\d{2}):(\d{2})/);
    if (iso) return `${iso[1]}:${iso[2]}`;
    return '';
}

export function dayActive(v: unknown): boolean {
    return v === true || v === 1 || v === '1';
}
